# Pattern: bail!("...", ...) -> return Err(BivvyError::GitOperation { message: format!("...", ...) })

# "Failed to query remote: {}" 
content = content.replace(
    '''bail!(
                    "Failed to query remote: {}",
                    String::from_utf8_lossy(&output.stderr)
                );''',
    '''return Err(BivvyError::GitOperation {
                    message: format!(
                        "Failed to query remote: {}",
                        String::from_utf8_lossy(&output.stderr)
                    ),
                });'''
)

# "Could not resolve ref..."
content = content.replace(
    '''bail!("Could not resolve ref '{refspec}' from {url}")''',
    '''return Err(BivvyError::GitOperation {
            message: format!("Could not resolve ref '{}' from {}", refspec, url),
